async function reindexIssueComments(
  orgId: OrgId,
  issueId: Issue["id"],
): Promise<void> {
  let cursor: string | null = null;
  for (;;) {
    const page = await commentRepo.listComments({
      orgId,
      issueId,
      includeArchived: false,
      limit: 100,
      cursor,
    });
    for (const comment of page.items) {
      const issue = await issueRepo.findIssueById(orgId, comment.issueId);
      await searchRepo.upsertSearchDocument(
        orgId,
        "comment",
        comment.id,
        comment.body,
        issue?.projectId ?? null,
      );
    }
    if (page.nextCursor === null) return;
    cursor = page.nextCursor;
  }
}

/**
 * Puts one subject back into the index, or drops it when it is gone or archived.
 * Every kind the event names is covered.
 */
async function reindexSubject(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  if (subjectKind === "issue") {
    const issue = await issueRepo.findIssueById(orgId, subjectId as Issue["id"]);
    if (issue && issue.archivedAt === null) {
      await indexIssue(orgId, issue);
      return;
    }
  } else if (subjectKind === "comment") {
    const comment = await commentRepo.findCommentById(
      orgId,
      subjectId as Comment["id"],
    );
    if (comment && comment.archivedAt === null) {
      await indexComment(orgId, comment);
      return;
    }
  } else if (subjectKind === "project") {
    const project = await projectRepo.findProjectById(
      orgId,
      subjectId as Project["id"],
    );
    if (project && project.archivedAt === null) {
      await indexProject(orgId, project);
      return;
    }
  }

  await removeFromIndex(orgId, subjectKind, subjectId);
}

